import { ref, computed } from 'vue';
import { analyzeFile, getBrokers } from '@/services/api';
import { useErrorHandler } from '@/composables/useErrorHandler';
export default {
  name: 'TransactionImportDialog',
  props: {
    modelValue: Boolean
  },
  emits: ['update:modelValue', 'import-confirmed'],
  setup(props, {
    emit
  }) {
    const dialog = computed({
      get: () => props.modelValue,
      set: value => emit('update:modelValue', value)
    });
    const file = ref(null);
    const isLoading = ref(false);
    const isAnalyzed = ref(false);
    const selectedBroker = ref(null);
    const brokers = ref([]);
    const fileId = ref(null);
    const brokerIdentified = ref(false);
    const identifiedBroker = ref(null);
    const {
      handleApiError
    } = useErrorHandler();
    const handleFileChange = () => {
      isAnalyzed.value = false;
      selectedBroker.value = null;
      brokerIdentified.value = false;
      identifiedBroker.value = null;
    };
    const closeDialog = () => {
      dialog.value = false;
      file.value = null;
      isAnalyzed.value = false;
      selectedBroker.value = null;
      fileId.value = null;
      brokerIdentified.value = false;
      identifiedBroker.value = null;
    };
    const analyzeFile = async () => {
      if (file.value) {
        isLoading.value = true;
        try {
          const result = await analyzeFile(file.value);
          isAnalyzed.value = true;
          fileId.value = result.fileId;
          brokers.value = await getBrokers();
          if (result.status === 'broker_identified') {
            brokerIdentified.value = true;
            identifiedBroker.value = result.identifiedBroker;
            selectedBroker.value = result.identifiedBroker.id;
          }
        } catch (error) {
          handleApiError(error);
        } finally {
          isLoading.value = false;
        }
      }
    };
    const confirmImport = () => {
      emit('import-confirmed', {
        fileId: fileId.value,
        brokerId: selectedBroker.value
      });
      closeDialog();
    };
    return {
      dialog,
      file,
      isLoading,
      isAnalyzed,
      selectedBroker,
      brokers,
      brokerIdentified,
      identifiedBroker,
      handleFileChange,
      closeDialog,
      analyzeFile,
      confirmImport
    };
  }
};
